INSERT INTO shared_location_revision (
    shared_location_revision_id, shared_location_id, revision_number,
    location_name, time_zone, status, effective_from, effective_to,
    supersedes_shared_location_revision_id, snapshot_digest,
    change_reason, created_by, created_at
) VALUES (
    #{sharedRevisionId},
    COALESCE(
        (SELECT availability.shared_location_id
         FROM company_location_availability availability
         JOIN location projection
           ON projection.location_id = availability.location_id
          AND projection.company_id = availability.company_id
          AND projection.location_code = #{row.locationCode}
         WHERE availability.location_id = #{row.locationId}
           AND availability.location_code = #{row.locationCode}
         LIMIT 1),
        #{row.sharedLocationId}
    ),
    #{sharedRevisionNumber}, #{row.locationName}, #{row.timeZone},
    #{row.status}, #{row.effectiveFrom}, #{row.effectiveTo},
    #{predecessorRevisionId}, #{snapshotDigest},
    #{row.changeReason}, #{row.updatedBy}, #{row.updatedAt}
)

mapper.update:
UPDATE shared_location_revision
SET effective_to = #{effectiveTo},
    snapshot_digest = #{snapshotDigest}
WHERE shared_location_revision_id = #{revisionId}
  AND effective_to IS NULL
  AND effective_from < #{effectiveTo}

mapper.select:
SELECT 
FROM location scoped
JOIN location_timeline timeline
  ON timeline.location_id = scoped.location_id
JOIN location_revision revision
  ON revision.location_revision_id = timeline.location_revision_id
WHERE scoped.location_id = #{locationId}
  AND timeline.business_effective_from <= #{asOf}
  AND timeline.recorded_at <= #{knowledgeAsOf}
  AND NOT EXISTS (
      SELECT 1
      FROM location_timeline newer
      WHERE newer.location_id = timeline.location_id
        AND newer.business_effective_from <= #{asOf}
        AND newer.recorded_at <= #{knowledgeAsOf}
        AND newer.event_sequence > timeline.event_sequence
  )
ORDER BY timeline.event_sequence, revision.location_revision_id

SELECT DISTINCT FROM location scoped JOIN company_location_availability availability ON availability.location_id = scoped.location_id AND availability.company_id = scoped.company_id AND availability.status = 'ACTIVE' JOIN shared_location shared ON shared.shared_location_id = availability.shared_location_id AND shared.location_code = scoped.location_code AND availability.location_code = scoped.location_code JOIN shared_location_revision shared_revision ON shared_revision.shared_location_id = shared.shared_location_id AND shared_revision.revision_number = ( SELECT MAX(latest.revision_number) FROM shared_location_revision latest WHERE latest.shared_location_id = shared.shared_location_id )
AND NOT EXISTS ( SELECT 1 FROM company_location_availability earlier JOIN location earlier_projection ON earlier_projection.location_id = earlier.location_id AND earlier_projection.company_id = earlier.company_id JOIN auth_principal_role_assignment earlier_assignment ON earlier_assignment.principal_id = #{principalId} JOIN auth_role_capability earlier_role_capability ON earlier_role_capability.role_id = earlier_assignment.role_id JOIN auth_capability earlier_capability ON earlier_capability.capability_id = earlier_role_capability.capability_id AND earlier_capability.capability_code = #{capability} JOIN auth_data_scope earlier_scope ON earlier_scope.scope_id = earlier_assignment.data_scope_id AND earlier_scope.scope_type = 'COMPANY' AND earlier_scope.company_id = earlier.company_id WHERE earlier.shared_location_id = availability.shared_location_id AND earlier.location_code = availability.location_code AND earlier.status = 'ACTIVE' AND earlier_projection.location_code = shared.location_code AND earlier.location_id < scoped.location_id AND earlier_assignment.valid_from <= #{at} AND (earlier_assignment.valid_to IS NULL OR earlier_assignment.valid_to > #{at}) AND earlier_scope.valid_from <= #{at} AND (earlier_scope.valid_to IS NULL OR earlier_scope.valid_to > #{at}) )
ORDER BY shared_revision.location_name, scoped.location_id LIMIT #{limit} OFFSET #{offset}

