SELECT (
    EXISTS (
        SELECT 1
        FROM shift_template template
        WHERE template.location_id = #{locationId}
    )
    OR EXISTS (
        SELECT 1
        FROM work_calendar calendar
        WHERE calendar.location_id = #{locationId}
    )
    OR EXISTS (
        SELECT 1
        FROM attendance_group_revision group_revision
        JOIN location_revision location_revision
          ON location_revision.location_revision_id =
                group_revision.location_revision_id
        WHERE location_revision.location_id = #{locationId}
    )
)

SELECT COUNT(DISTINCT scoped.attendance_group_id)
FROM attendance_group scoped
JOIN attendance_group_timeline timeline
  ON timeline.attendance_group_id = scoped.attendance_group_id


    AND timeline.business_effective_from <= #{asOf}
    AND timeline.recorded_at <= #{at}
    AND NOT EXISTS (
        SELECT 1
        FROM attendance_group_timeline newer
        WHERE newer.attendance_group_id = timeline.attendance_group_id
          AND newer.business_effective_from <= #{asOf}
          AND newer.recorded_at <= #{at}
          AND newer.event_sequence > timeline.event_sequence
    )


    AND timeline.event_sequence = (
        SELECT MAX(latest.event_sequence)
        FROM attendance_group_timeline latest
        WHERE latest.attendance_group_id = scoped.attendance_group_id
    )

SELECT COUNT(*)
FROM attendance_group_revision revision
WHERE revision.attendance_group_id = #{groupId}

